'use client';

import * as React from 'react';
import { Slider as SliderPrimitive } from 'radix-ui';
import { type Transition } from 'motion/react';

import { ReducedMotionConfig, useTempoTransition } from '../../../utils/motion';
import {
  SLIDER_TRANSITION,
  SliderMotionProvider,
  useSliderMotion,
  useSliderPartMotion,
  useSliderRootMotion,
  useThumbStretch,
} from '../../../internal/slider';
import { MotionSlot, slotChild } from '../../../internal/modal-motion';

type SliderProps = SliderPrimitive.SliderProps;
type SliderTrackProps = SliderPrimitive.SliderTrackProps;
type SliderRangeProps = SliderPrimitive.SliderRangeProps & RangeAnimationProps;
type SliderThumbProps = SliderPrimitive.SliderThumbProps & ThumbAnimationProps;

type RangeAnimationProps = {
  transition?: Transition;
};

type ThumbAnimationProps = {
  transition?: Transition;
};

function Root(props: React.ComponentProps<typeof SliderPrimitive.Root>) {
  return (
    <ReducedMotionConfig>
      <RootMotion {...props} />
    </ReducedMotionConfig>
  );
}

function RootMotion({
  onPointerDownCapture,
  ...props
}: React.ComponentProps<typeof SliderPrimitive.Root>) {
  const controlled = props.value !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(
    props.defaultValue ?? [props.min ?? 0],
  );
  const values = controlled ? props.value : uncontrolled;
  const wasControlledRef = React.useRef(controlled);
  React.useEffect(() => {
    if (wasControlledRef.current === controlled) return;
    const [from, to] = controlled
      ? ['uncontrolled', 'controlled']
      : ['controlled', 'uncontrolled'];
    console.warn(
      `Slider is changing from ${from} to ${to}. Components should not switch from controlled to uncontrolled (or vice versa). Decide between using a controlled or uncontrolled value for the lifetime of the component.`,
    );
    wasControlledRef.current = controlled;
  }, [controlled]);

  const motionContext = useSliderRootMotion({
    disabled: props.disabled,
    valuesKey: String(values),
  });

  return (
    <SliderMotionProvider value={motionContext}>
      <SliderPrimitive.Root
        {...props}
        value={values}
        onValueChange={(next) => {
          if (!controlled) setUncontrolled(next);
          props.onValueChange?.(next);
        }}
        onPointerDownCapture={(event) => {
          onPointerDownCapture?.(event);
          motionContext.startPress(event);
        }}
      />
    </SliderMotionProvider>
  );
}

const Track = SliderPrimitive.Track;

function Range({
  transition,
  asChild,
  children,
  ...props
}: React.ComponentProps<typeof SliderPrimitive.Range> & RangeAnimationProps) {
  const spring = useTempoTransition(transition ?? SLIDER_TRANSITION);
  const { ref, transform } = useSliderPartMotion('range', spring);

  const slot = slotChild(asChild, children);
  return (
    <SliderPrimitive.Range {...props} asChild>
      <MotionSlot
        element={slot.element}
        as="span"
        ref={ref as React.Ref<HTMLSpanElement>}
        style={{ transform, transformOrigin: '0 0' }}
      >
        {slot.inner}
      </MotionSlot>
    </SliderPrimitive.Range>
  );
}

function Thumb({
  transition,
  onFocus,
  onBlur,
  asChild,
  children,
  ...props
}: React.ComponentProps<typeof SliderPrimitive.Thumb> & ThumbAnimationProps) {
  const spring = useTempoTransition(transition ?? SLIDER_TRANSITION);
  const { isPressing } = useSliderMotion();
  const [isFocused, setIsFocused] = React.useState(false);
  const { ref, transform } = useSliderPartMotion('thumb', spring);

  const isPressed = isPressing && isFocused;
  useThumbStretch(ref, isPressed, spring);

  const slot = slotChild(asChild, children);
  return (
    <SliderPrimitive.Thumb
      data-pressed={isPressed || undefined}
      {...props}
      onFocus={(event) => {
        setIsFocused(true);
        onFocus?.(event);
      }}
      onBlur={(event) => {
        setIsFocused(false);
        onBlur?.(event);
      }}
      asChild
    >
      <MotionSlot
        element={slot.element}
        as="span"
        ref={ref as React.Ref<HTMLSpanElement>}
        style={{ transform }}
      >
        {slot.inner}
      </MotionSlot>
    </SliderPrimitive.Thumb>
  );
}

const createSliderScope: typeof SliderPrimitive.createSliderScope =
  SliderPrimitive.createSliderScope;

const unstable_BubbleInput = SliderPrimitive.unstable_BubbleInput;
const unstable_SliderBubbleInput = SliderPrimitive.unstable_SliderBubbleInput;
const unstable_SliderThumbProvider =
  SliderPrimitive.unstable_SliderThumbProvider;
const unstable_SliderThumbTrigger = SliderPrimitive.unstable_SliderThumbTrigger;
const unstable_ThumbProvider = SliderPrimitive.unstable_ThumbProvider;
const unstable_ThumbTrigger = SliderPrimitive.unstable_ThumbTrigger;
type unstable_SliderBubbleInputProps =
  SliderPrimitive.unstable_SliderBubbleInputProps;
type unstable_SliderThumbProviderProps =
  SliderPrimitive.unstable_SliderThumbProviderProps;
type unstable_SliderThumbTriggerProps =
  SliderPrimitive.unstable_SliderThumbTriggerProps;

Root.displayName = 'Slider';
Range.displayName = 'SliderRange';
Thumb.displayName = 'SliderThumb';

export {
  Root,
  Root as Slider,
  Track,
  Range,
  Thumb,
  Track as SliderTrack,
  Range as SliderRange,
  Thumb as SliderThumb,
  createSliderScope,
  unstable_BubbleInput,
  unstable_SliderBubbleInput,
  unstable_SliderThumbProvider,
  unstable_SliderThumbTrigger,
  unstable_ThumbProvider,
  unstable_ThumbTrigger,
  type SliderProps,
  type SliderTrackProps,
  type SliderRangeProps,
  type SliderThumbProps,
  type unstable_SliderBubbleInputProps,
  type unstable_SliderThumbProviderProps,
  type unstable_SliderThumbTriggerProps,
};

'use client';

import * as React from 'react';
import { Switch as SwitchPrimitive } from 'radix-ui';
import { motion } from 'motion/react';

import { ReducedMotionConfig } from '../../../utils/motion';
import { mergeRefs } from '../../../internal/controls/indicator';
import {
  SwitchPressedContext,
  useSwitchThumb,
  type ThumbAnimationProps,
} from '../../../internal/controls/thumb';

type SwitchProps = SwitchPrimitive.SwitchProps;
type SwitchThumbProps = SwitchPrimitive.SwitchThumbProps & ThumbAnimationProps;

function Root({
  asChild,
  children,
  ...props
}: React.ComponentProps<typeof SwitchPrimitive.Root>) {
  const [pressed, setPressed] = React.useState(false);

  if (asChild)
    return (
      <SwitchPrimitive.Root {...props} asChild>
        {children}
      </SwitchPrimitive.Root>
    );

  return (
    <SwitchPressedContext value={pressed}>
      <SwitchPrimitive.Root {...props} asChild>
        <motion.button
          onTapStart={() => {
            if (!props.disabled) setPressed(true);
          }}
          onTap={() => setPressed(false)}
          onTapCancel={() => setPressed(false)}
        >
          {children}
        </motion.button>
      </SwitchPrimitive.Root>
    </SwitchPressedContext>
  );
}

function Thumb({
  asChild,
  children,
  transition,
  ...props
}: React.ComponentProps<typeof SwitchPrimitive.Thumb> & ThumbAnimationProps) {
  if (asChild)
    return (
      <SwitchPrimitive.Thumb {...props} asChild>
        {children}
      </SwitchPrimitive.Thumb>
    );

  return (
    <ReducedMotionConfig>
      <SwitchPrimitive.Thumb {...props} asChild>
        <AnimatedThumb transition={transition}>{children}</AnimatedThumb>
      </SwitchPrimitive.Thumb>
    </ReducedMotionConfig>
  );
}

function AnimatedThumb({
  transition,
  ref,
  ...props
}: React.ComponentPropsWithRef<'span'> &
  ThumbAnimationProps & { 'data-state'?: string }) {
  const localRef = React.useRef<HTMLSpanElement>(null);
  const mergedRef = React.useMemo(() => mergeRefs(ref, localRef), [ref]);
  useSwitchThumb(() => localRef.current, {
    checked: props['data-state'] === 'checked',
    pressed: React.use(SwitchPressedContext),
    transition,
  });
  return <span {...props} ref={mergedRef} />;
}

const createSwitchScope: typeof SwitchPrimitive.createSwitchScope =
  SwitchPrimitive.createSwitchScope;

const unstable_SwitchProvider = SwitchPrimitive.unstable_SwitchProvider;
const unstable_SwitchTrigger = SwitchPrimitive.unstable_SwitchTrigger;
const unstable_SwitchBubbleInput = SwitchPrimitive.unstable_SwitchBubbleInput;
type unstable_SwitchProviderProps =
  SwitchPrimitive.unstable_SwitchProviderProps;
type unstable_SwitchTriggerProps = SwitchPrimitive.unstable_SwitchTriggerProps;
type unstable_SwitchBubbleInputProps =
  SwitchPrimitive.unstable_SwitchBubbleInputProps;

Root.displayName = 'Switch';
Thumb.displayName = 'SwitchThumb';

export {
  Root,
  Thumb,
  Root as Switch,
  Thumb as SwitchThumb,
  createSwitchScope,
  unstable_SwitchProvider,
  unstable_SwitchProvider as unstable_Provider,
  unstable_SwitchTrigger,
  unstable_SwitchTrigger as unstable_Trigger,
  unstable_SwitchBubbleInput,
  unstable_SwitchBubbleInput as unstable_BubbleInput,
  type SwitchProps,
  type SwitchThumbProps,
  type unstable_SwitchProviderProps,
  type unstable_SwitchTriggerProps,
  type unstable_SwitchBubbleInputProps,
};

'use client';

import * as React from 'react';
import { Tabs as TabsPrimitive } from 'radix-ui';
import type { Transition } from 'motion/react';

import { getStrictContext } from '../../../utils/strict-context';
import { ReducedMotionConfig } from '../../../utils/motion';
import {
  TAB_ATTRIBUTE,
  usePanelMotion,
  useTabsIndicator,
} from '../../../internal/tabs';

const [ValueProvider, useValue] = getStrictContext<{
  value: string | undefined;
}>('Tabs.Root');

type TabsProps = TabsPrimitive.TabsProps;
type TabsListProps = TabsPrimitive.TabsListProps & ListAnimationProps;
type TabsTriggerProps = TabsPrimitive.TabsTriggerProps;
type TabsContentProps = TabsPrimitive.TabsContentProps & ContentAnimationProps;

type ListAnimationProps = {
  transition?: Transition;
};

type ContentAnimationProps = {
  transition?: Transition;
  exitTransition?: Transition;
};

function Root({
  value: valueProp,
  defaultValue,
  onValueChange,
  ...props
}: React.ComponentProps<typeof TabsPrimitive.Root>) {
  const controlled = valueProp !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const value = controlled ? valueProp : uncontrolled;

  const handleValueChange = (next: string) => {
    if (!controlled) setUncontrolled(next);
    onValueChange?.(next);
  };

  return (
    <ValueProvider value={{ value }}>
      <ReducedMotionConfig>
        <TabsPrimitive.Root
          {...props}
          value={value ?? ''}
          onValueChange={handleValueChange}
        />
      </ReducedMotionConfig>
    </ValueProvider>
  );
}

function List({
  ref,
  transition,
  children,
  ...props
}: React.ComponentProps<typeof TabsPrimitive.List> & ListAnimationProps) {
  const [list, setList] = React.useState<HTMLDivElement | null>(null);
  const { indicator, listProps } = useTabsIndicator(list, {
    transition,
    enabled: !props.asChild,
  });

  return (
    <TabsPrimitive.List
      {...props}
      {...listProps}
      ref={(node) => {
        setList(node);
        if (typeof ref === 'function') return ref(node);
        if (ref) ref.current = node;
      }}
    >
      {props.asChild ? (
        children
      ) : (
        <>
          {indicator}
          {children}
        </>
      )}
    </TabsPrimitive.List>
  );
}

function Trigger(props: React.ComponentProps<typeof TabsPrimitive.Trigger>) {
  return <TabsPrimitive.Trigger {...{ [TAB_ATTRIBUTE]: '' }} {...props} />;
}

function Content({
  ref,
  forceMount,
  hidden,
  inert,
  transition,
  exitTransition,
  ...props
}: React.ComponentProps<typeof TabsPrimitive.Content> & ContentAnimationProps) {
  const { value } = useValue();
  const active = value === props.value;
  const {
    ref: panelRef,
    waiting,
    leaving,
  } = usePanelMotion(active, { transition, exitTransition });

  return (
    <TabsPrimitive.Content
      {...props}
      ref={(node: HTMLDivElement | null) => {
        panelRef.current = node;
        if (typeof ref === 'function') return ref(node);
        if (ref) ref.current = node;
      }}
      forceMount={forceMount || leaving ? true : undefined}
      hidden={hidden || waiting || (!active && !leaving) || undefined}
      inert={inert || leaving || undefined}
    />
  );
}

const createTabsScope: typeof TabsPrimitive.createTabsScope =
  TabsPrimitive.createTabsScope;

Root.displayName = 'Tabs';
List.displayName = 'TabsList';
Trigger.displayName = 'TabsTrigger';
Content.displayName = 'TabsContent';

export {
  Root,
  Root as Tabs,
  List,
  Trigger,
  Content,
  List as TabsList,
  Trigger as TabsTrigger,
  Content as TabsContent,
  createTabsScope,
  type TabsProps,
  type TabsListProps,
  type TabsTriggerProps,
  type TabsContentProps,
};

'use client';

import * as React from 'react';
import { ToggleGroup as ToggleGroupPrimitive } from 'radix-ui';
import { motion, type Transition } from 'motion/react';

import { ReducedMotionConfig } from '../../../utils/motion';
import { usePressMotion } from '../../../internal/controls/press';
import { mergeRefs } from '../../../internal/controls/indicator';
import {
  toggleGroupItemProps,
  useToggleGroupHighlight,
} from '../../../internal/controls/highlight';

type RootAnimationProps = {
  transition?: Transition;
};

type ItemAnimationProps = {
