const VISUALLY_HIDDEN: React.CSSProperties = {
  position: 'absolute',
  width: 1,
  height: 1,
  padding: 0,
  margin: -1,
  overflow: 'hidden',
  clip: 'rect(0, 0, 0, 0)',
  whiteSpace: 'nowrap',
  borderWidth: 0,
};

let segmenter: Intl.Segmenter | null | undefined;

function splitGraphemes(text: string): string[] {
  if (segmenter === undefined) {
    segmenter =
      typeof Intl !== 'undefined' && typeof Intl.Segmenter === 'function'
        ? new Intl.Segmenter(undefined, { granularity: 'grapheme' })
        : null;
  }
  if (!segmenter) return Array.from(text);
  return Array.from(segmenter.segment(text), (s) => s.segment);
}

export { VISUALLY_HIDDEN, splitGraphemes };

'use client';

import * as React from 'react';
import {
  animate,
  useMotionValue,
  useMotionValueEvent,
  type SpringOptions,
  type Transition,
} from 'motion/react';

import {
  useIsInView,
  type UseIsInViewOptions,
} from '../../../utils/use-is-in-view';
import {
  motionTokens,
  ReducedMotionConfig,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';
import { VISUALLY_HIDDEN } from '../_text';

const DEFAULT_TRANSITION: SpringOptions = {
  stiffness: motionTokens.spring.number.stiffness,
  damping: motionTokens.spring.number.damping,
};

function resolveTransition(transition: SpringOptions | Transition): Transition {
  if ('type' in transition || 'ease' in transition) {
    return transition as Transition;
  }
  return {
    type: 'spring',
    restDelta: 0.001,
    restSpeed: 0.01,
    ...transition,
  } as Transition;
}

type FormatOptions = {
  decimals: number;
  decimalSeparator: string;
  thousandSeparator: string | undefined;
  padLength: number;
};

function formatNumber(
  value: number,
  { decimals, decimalSeparator, thousandSeparator, padLength }: FormatOptions,
) {
  const fixed = Math.abs(value).toFixed(decimals);
  const sign = value < 0 && Number(fixed) !== 0 ? '-' : '';
  const [intPart = '0', fracPart] = fixed.split('.');
  const padded = intPart.padStart(padLength, '0');
  const paddedInt =
    thousandSeparator === undefined
      ? padded
      : padded.replace(/\B(?=(\d{3})+$)/g, thousandSeparator);
  return fracPart
    ? `${sign}${paddedInt}${decimalSeparator}${fracPart}`
    : `${sign}${paddedInt}`;
}

type CountingNumberProps = Omit<React.ComponentProps<'span'>, 'children'> & {
  number: number;
  fromNumber?: number;
  padStart?: boolean;
  decimalSeparator?: string;
  decimalPlaces?: number;
  thousandSeparator?: string;
  transition?: SpringOptions | Transition;
  delay?: number;
  initiallyStable?: boolean;
} & UseIsInViewOptions;

function CountingNumber(props: CountingNumberProps) {
  return (
    <ReducedMotionConfig remount>
      <CountingNumberContent {...props} />
    </ReducedMotionConfig>
  );
}

function CountingNumberContent({
  ref,
  number,
  fromNumber = 0,
  padStart = false,
  inView = false,
  inViewMargin = '0px',
  inViewOnce = true,
  decimalSeparator = '.',
  thousandSeparator,
  transition: transitionProp,
  decimalPlaces = 0,
  delay = 0,
  initiallyStable = false,
  ...props
}: CountingNumberProps) {
  const { ref: localRef, isInView } = useIsInView(
    ref as React.Ref<HTMLSpanElement>,
    { inView, inViewOnce, inViewMargin },
  );
  const visualRef = React.useRef<HTMLSpanElement>(null);
  const reduce = useShouldReduceMotion();
  const defaultTransition = useTempoTransition(
    DEFAULT_TRANSITION as Transition,
  );
  const transition = transitionProp ?? defaultTransition;

  const formatOptions: FormatOptions = {
    decimals: decimalPlaces,
    decimalSeparator,
    thousandSeparator,
    padLength: padStart ? Math.floor(Math.abs(number)).toString().length : 0,
  };

  const value = useMotionValue(initiallyStable ? number : fromNumber);

  useMotionValueEvent(value, 'change', (latest) => {
    const node = visualRef.current;
    if (!node) return;
    const text = formatNumber(latest, formatOptions);
    if (node.firstChild instanceof Text) node.firstChild.nodeValue = text;
    else node.textContent = text;
  });

  const transitionRef = React.useRef(transition);
  React.useEffect(() => {
    transitionRef.current = transition;
  });

  React.useEffect(() => {
    if (!isInView) return;

    if (reduce) {
      value.jump(number);
      return;
    }

    const timeoutId = setTimeout(() => {
      animate(value, number, resolveTransition(transitionRef.current));
    }, delay);

    return () => clearTimeout(timeoutId);
  }, [isInView, number, value, delay, reduce]);

  React.useEffect(() => () => value.stop(), [value]);

  return (
    <span ref={localRef} data-slot="counting-number" {...props}>
      <span aria-hidden="true" ref={visualRef}>
        {formatNumber(value.get(), formatOptions)}
      </span>
      <span className="sr-only" style={VISUALLY_HIDDEN}>
        {formatNumber(number, formatOptions)}
      </span>
    </span>
  );
}

export { CountingNumber, type CountingNumberProps };

'use client';

import * as React from 'react';
import {
  animate,
  motion,
  useInView,
  useMotionValue,
  type AnimationPlaybackControls,
  type Transition,
} from 'motion/react';

import { usePageVisible } from '../../../utils/use-page-visible';
import {
  ReducedMotionConfig,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';

const DEFAULT_GRADIENT =
  'linear-gradient(90deg, #3b82f6 0%, #a855f7 20%, #ec4899 50%, #a855f7 80%, #3b82f6 100%)';

const DEFAULT_TRANSITION: Transition = {
  duration: 50,
  repeat: Infinity,
  ease: 'linear',
};

const START_POSITION = '0% 0%';
const END_POSITION = '500% 100%';

type GradientTextProps = Omit<React.ComponentProps<'span'>, 'children'> & {
  text: string;
  gradient?: string;
  neon?: boolean;
  transition?: Transition;
};

function GradientText(props: GradientTextProps) {
  return (
    <ReducedMotionConfig>
      <GradientTextContent {...props} />
    </ReducedMotionConfig>
  );
}

function GradientTextContent({
  ref,
  text,
  style,
  gradient = DEFAULT_GRADIENT,
  neon = false,
  transition: transitionProp,
  ...props
}: GradientTextProps) {
  const defaultTransition = useTempoTransition(DEFAULT_TRANSITION);
  const transition = transitionProp ?? defaultTransition;
  const localRef = React.useRef<HTMLSpanElement>(null);
  React.useImperativeHandle(ref, () => localRef.current as HTMLSpanElement);

  const inView = useInView(localRef);
  const pageVisible = usePageVisible();
  const reduce = useShouldReduceMotion();
  const playing = inView && pageVisible;

  const backgroundPosition = useMotionValue(START_POSITION);
  const controlsRef = React.useRef<AnimationPlaybackControls | null>(null);

  const transitionKey = JSON.stringify(transition);
  const transitionRef = React.useRef(transition);
  React.useEffect(() => {
    transitionRef.current = transition;
  });

  React.useEffect(() => {
    if (reduce) return;
    const controls = animate(
      backgroundPosition,
      [START_POSITION, END_POSITION],
      transitionRef.current,
    );
    controlsRef.current = controls;
    return () => {
      controls.stop();
      controlsRef.current = null;
      backgroundPosition.set(START_POSITION);
    };
  }, [backgroundPosition, reduce, transitionKey]);

  React.useEffect(() => {
    const controls = controlsRef.current;
    if (!controls) return;
    if (playing) controls.play();
    else controls.pause();
  }, [playing, reduce, transitionKey]);

  const layerStyle = {
    backgroundImage: gradient,
    margin: 0,
    color: 'transparent',
    backgroundClip: 'text',
    WebkitBackgroundClip: 'text',
    backgroundSize: '700% 100%',
    backgroundPosition,
  };

  return (
    <span
      ref={localRef}
      data-slot="gradient-text"
      style={{ position: 'relative', display: 'inline-block', ...style }}
      {...props}
    >
      <motion.span style={layerStyle}>{text}</motion.span>

      {neon && (
        <motion.span
          aria-hidden
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            mixBlendMode: 'plus-lighter',
            filter: 'blur(8px)',
            ...layerStyle,
          }}
        >
          {text}
        </motion.span>
      )}
    </span>
  );
}

export { GradientText, type GradientTextProps };

'use client';

import * as React from 'react';
import { motion, type HTMLMotionProps, type Transition } from 'motion/react';

import {
  useIsInView,
  type UseIsInViewOptions,
} from '../../../utils/use-is-in-view';
import {
  ReducedMotionConfig,
  transition as motionTransition,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';

const HIDDEN_SIZE = '0% 100%';
const VISIBLE_SIZE = '100% 100%';

