'use client';

import * as React from 'react';
import {
  animate,
  motion,
  useMotionValue,
  useMotionValueEvent,
  useSpring,
  useTransform,
  type HTMLMotionProps,
  type MotionValue,
  type SpringOptions,
  type Transition,
} from 'motion/react';

import {
  useIsInView,
  type UseIsInViewOptions,
} from '../../../utils/use-is-in-view';
import {
  motionTokens,
  ReducedMotionConfig,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';
import { VISUALLY_HIDDEN } from '../_text';

const ROLLER_TRANSITION: SpringOptions = {
  stiffness: 200,
  damping: 20,
  mass: 0.4,
};

const COUNT_TRANSITION: Transition = {
  ...motionTokens.spring.number,
  restDelta: 0.001,
  restSpeed: 0.01,
};

function intLength(units: number, factor: number) {
  return Math.floor(Math.abs(units) / factor).toString().length;
}

type Rolling = {
  units: MotionValue<number>;
  reduce: boolean;
  transition: SpringOptions;
};

type SlidingNumberRollerProps = Rolling & {
  place: number;
};

function SlidingNumberRoller({
  units,
  place,
  reduce,
  transition,
}: SlidingNumberRollerProps) {
  const digitOf = React.useCallback(
    (value: number) => Math.floor(Math.abs(value) / place) % 10,
    [place],
  );

  const [startDigit] = React.useState(() =>
    digitOf(units.getPrevious() ?? units.get()),
  );
  const position = useSpring(startDigit, transition);

  const roll = React.useCallback(
    (value: number) => {
      const digit = digitOf(value);
      if (reduce) position.jump(digit);
      else position.set(digit);
    },
    [digitOf, reduce, position],
  );

  useMotionValueEvent(units, 'change', roll);
  React.useEffect(() => roll(units.get()), [roll, units]);

  return (
    <span
      aria-hidden="true"
      data-slot="sliding-number-roller"
      style={{
        position: 'relative',
        display: 'inline-block',
        width: '1ch',
        overflowX: 'visible',
        overflowY: 'clip',
        lineHeight: 1,
        fontVariantNumeric: 'tabular-nums',
      }}
    >
      <span style={{ visibility: 'hidden' }}>0</span>
      {Array.from({ length: 10 }, (_, i) => (
        <SlidingNumberDisplay key={i} position={position} number={i} />
      ))}
    </span>
  );
}

type SlidingNumberDisplayProps = {
  position: MotionValue<number>;
  number: number;
};

function SlidingNumberDisplay({ position, number }: SlidingNumberDisplayProps) {
  const transform = useTransform(position, (latest) => {
    const current = ((latest % 10) + 10) % 10;
    let offset = (10 + number - current) % 10;
    if (offset > 5) offset -= 10;
    return `translateY(${offset * 100}%)`;
  });

  return (
    <motion.span
      data-slot="sliding-number-display"
      style={{
        transform,
        position: 'absolute',
        inset: 0,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      {number}
    </motion.span>
  );
}

type SlidingNumberProps = Omit<HTMLMotionProps<'span'>, 'children'> & {
  number: number;
  fromNumber?: number;
  onNumberChange?: (number: number) => void;
  padStart?: boolean;
  decimalSeparator?: string;
  decimalPlaces?: number;
  thousandSeparator?: string;
  transition?: SpringOptions;
  delay?: number;
  initiallyStable?: boolean;
} & UseIsInViewOptions;

function SlidingNumber(props: SlidingNumberProps) {
  return (
    <ReducedMotionConfig remount>
      <SlidingNumberContent {...props} />
    </ReducedMotionConfig>
  );
}

function SlidingNumberContent({
  ref,
  number,
  fromNumber,
  onNumberChange,
  inView = false,
  inViewMargin = '0px',
  inViewOnce = true,
  padStart = false,
  decimalSeparator = '.',
  decimalPlaces = 0,
  thousandSeparator,
  transition: transitionProp,
  delay = 0,
  initiallyStable = false,
  style,
  ...props
}: SlidingNumberProps) {
  const { ref: localRef, isInView } = useIsInView(
    ref as React.Ref<HTMLSpanElement>,
    { inView, inViewOnce, inViewMargin },
  );
  const reduce = useShouldReduceMotion();

  const defaultRollerTransition = useTempoTransition(
    ROLLER_TRANSITION as Transition,
  ) as SpringOptions;
  const transition = transitionProp ?? defaultRollerTransition;

  const countTransition = useTempoTransition(COUNT_TRANSITION);
  const countTransitionRef = React.useRef(countTransition);
  React.useEffect(() => {
    countTransitionRef.current = countTransition;
  });

  const isCounting = fromNumber !== undefined;
  const decimals = decimalPlaces;
  const factor = Math.pow(10, decimals);
  const toUnits = (value: number) => Math.round(value * factor);

  const initialValue = initiallyStable ? number : (fromNumber ?? 0);
  const value = useMotionValue(initialValue);
  const units = useMotionValue(toUnits(initialValue));

  const [layout, setLayout] = React.useState(() => ({
    intLength: intLength(toUnits(initialValue), factor),
    negative: toUnits(initialValue) < 0,
  }));

  useMotionValueEvent(value, 'change', (latest) => units.set(toUnits(latest)));
  useMotionValueEvent(units, 'change', (latest) => {
    const next = {
      intLength: intLength(latest, factor),
      negative: latest < 0,
    };
    setLayout((prev) =>
      prev.intLength === next.intLength && prev.negative === next.negative
        ? prev
        : next,
    );
    onNumberChange?.(latest / factor);
  });

  React.useEffect(() => {
    units.set(Math.round(value.get() * factor));
  }, [factor, units, value]);

  React.useEffect(() => {
    if (!isInView) {
      if (!isCounting && !initiallyStable) value.jump(0);
      return;
    }

    const timeoutId = setTimeout(
      () => {
        if (isCounting && !reduce)
          animate(value, number, countTransitionRef.current);
        else value.jump(number);
      },
      reduce ? 0 : delay,
    );
    return () => clearTimeout(timeoutId);
  }, [isInView, isCounting, initiallyStable, number, value, delay, reduce]);

  React.useEffect(() => () => value.stop(), [value]);

  const shownIntLength = padStart
    ? Math.max(Math.floor(Math.abs(number)).toString().length, layout.intLength)
    : layout.intLength;

  const intPlaces = Array.from(
    { length: shownIntLength },
    (_, i) => Math.pow(10, shownIntLength - i - 1) * factor,
  );
  const decPlaces = Array.from({ length: decimals }, (_, i) =>
    Math.pow(10, decimals - i - 1),
  );

  const rolling: Rolling = { units, reduce, transition };

  return (
    <motion.span
      ref={localRef}
      data-slot="sliding-number"
      style={{ display: 'inline-flex', alignItems: 'center', ...style }}
      {...props}
    >
      <span className="sr-only" style={VISUALLY_HIDDEN}>
        {formatNumber(number, {
          decimals,
          decimalSeparator,
          thousandSeparator,
          padLength: padStart ? shownIntLength : 0,
        })}
      </span>

      {layout.negative && (
        <span aria-hidden="true" style={{ marginRight: '0.25rem' }}>
          -
        </span>
      )}

      {intPlaces.map((place, idx) => {
        const digitsToRight = intPlaces.length - idx - 1;
        const isSeparatorPosition =
          thousandSeparator !== undefined &&
          digitsToRight > 0 &&
          digitsToRight % 3 === 0;

        return (
          <React.Fragment key={`int-${place}`}>
            <SlidingNumberRoller place={place} {...rolling} />
            {isSeparatorPosition && (
              <span aria-hidden="true">{thousandSeparator}</span>
            )}
          </React.Fragment>
        );
      })}

      {decimals > 0 && (
        <>
          <span aria-hidden="true">{decimalSeparator}</span>
          {decPlaces.map((place) => (
            <SlidingNumberRoller
              key={`dec-${place}`}
              place={place}
              {...rolling}
            />
          ))}
        </>
      )}
    </motion.span>
  );
}

type FormatOptions = {
  decimals: number;
  decimalSeparator: string;
  thousandSeparator?: string;
  padLength: number;
};

function formatNumber(
  value: number,
  { decimals, decimalSeparator, thousandSeparator, padLength }: FormatOptions,
) {
  const fixed = Math.abs(value).toFixed(decimals);
  const sign = value < 0 && Number(fixed) !== 0 ? '-' : '';
  const [intPart = '0', fracPart] = fixed.split('.');
  let int = intPart.padStart(padLength, '0');
  if (thousandSeparator !== undefined) {
    int = int.replace(/\B(?=(\d{3})+(?!\d))/g, thousandSeparator);
  }
  return fracPart
    ? `${sign}${int}${decimalSeparator}${fracPart}`
    : `${sign}${int}`;
}

export { SlidingNumber, type SlidingNumberProps };

'use client';

import * as React from 'react';
import {
  animate,
  motion,
  useMotionValue,
  useTransform,
  type AnimationPlaybackControls,
  type HTMLMotionProps,
  type Transition,
} from 'motion/react';

import {
  ReducedMotionConfig,
  motionTokens,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';

type SlidingTextDirection = 'up' | 'down';

type SlidingTextTrigger = 'hover' | 'click';

const BLEED = '0.25em';

const GAP = '0.6em';

const DEFAULT_TRANSITION: Transition = {
  duration: 0.25,
  ease: motionTokens.ease.fill,
};

type SlidingTextProps = Omit<HTMLMotionProps<'span'>, 'children'> & {
  text: string;
  direction?: SlidingTextDirection;
  trigger?: SlidingTextTrigger;
  transition?: Transition;
};

function SlidingText(props: SlidingTextProps) {
  return (
    <ReducedMotionConfig>
      <SlidingTextContent {...props} />
    </ReducedMotionConfig>
  );
}

function SlidingTextContent({
  text,
  direction = 'down',
  trigger = 'hover',
  transition: transitionProp,
  style,
  onHoverStart,
  onHoverEnd,
  onClick,
  ...props
}: SlidingTextProps) {
  const reduce = useShouldReduceMotion();
  const defaultTransition = useTempoTransition(DEFAULT_TRANSITION);
  const transition = transitionProp ?? defaultTransition;
  const sign = direction === 'down' ? 1 : -1;

  const progress = useMotionValue(0);
  const y = useTransform(progress, (value) => {
    const lap = sign * (value - Math.floor(value));
    return lap === 0 ? '0%' : `calc(${lap * 100}% + ${lap} * ${GAP})`;
  });
  const targetRef = React.useRef(0);
  const controlsRef = React.useRef<AnimationPlaybackControls | null>(null);

  React.useEffect(() => () => controlsRef.current?.stop(), []);

  const slideTo = (target: number) => {
    targetRef.current = target;
    controlsRef.current?.stop();
    if (reduce) {
      progress.jump(target);
      return;
    }
    controlsRef.current = animate(progress, target, transition);
  };

  return (
    <motion.span
      data-slot="sliding-text"
      data-direction={direction}
      data-trigger={trigger}
      {...props}
      style={{
        position: 'relative',
        display: 'inline-block',
        overflow: 'clip',
        paddingBlock: BLEED,
        marginBlock: `calc(-1 * ${BLEED})`,
        ...style,
      }}
      onHoverStart={(event, info) => {
        if (trigger === 'hover') slideTo(1);
        onHoverStart?.(event, info);
      }}
      onHoverEnd={(event, info) => {
        if (trigger === 'hover') slideTo(0);
        onHoverEnd?.(event, info);
      }}
      onClick={(event) => {
        if (trigger === 'click') slideTo(Math.round(targetRef.current) + 1);
        onClick?.(event);
      }}
    >
      <motion.span
        data-slot="sliding-text-track"
        style={{ position: 'relative', display: 'inline-block', y }}
      >
        {text}
        <span
          data-slot="sliding-text-copy"
          aria-hidden="true"
          style={{
            position: 'absolute',
            left: 0,
            top: `calc(${-sign * 100}% - ${sign} * ${GAP})`,
            width: '100%',
          }}
        >
          {text}
        </span>
      </motion.span>
    </motion.span>
  );
}

export {
  SlidingText,
  type SlidingTextProps,
  type SlidingTextDirection,
  type SlidingTextTrigger,
};

'use client';

import * as React from 'react';
import {
  motion,
  type Variants,
  type TargetAndTransition,
  type HTMLMotionProps,
  type Transition,
} from 'motion/react';

import {
  useIsInView,
  type UseIsInViewOptions,
} from '../../../utils/use-is-in-view';
import {
  ReducedMotionConfig,
  transition as motionTransition,
  useMotionTokens,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';
import { VISUALLY_HIDDEN, splitGraphemes } from '../_text';

type DefaultSplittingTextProps = Omit<
  HTMLMotionProps<'div'>,
  'children' | 'initial' | 'animate' | 'transition'
> & {
  initial?: TargetAndTransition;
  animate?: TargetAndTransition;
  transition?: Transition;
  stagger?: number;
  delay?: number;
  disableAnimation?: boolean;
} & UseIsInViewOptions;

type CharsOrWordsSplittingTextProps = DefaultSplittingTextProps & {
  type?: 'chars' | 'words';
  text: string;
};

type LinesSplittingTextProps = DefaultSplittingTextProps & {
  type?: 'lines';
  text: string[];
};

type SplittingTextProps =
  CharsOrWordsSplittingTextProps | LinesSplittingTextProps;

const DEFAULT_INITIAL: TargetAndTransition = { x: 150, opacity: 0 };
const DEFAULT_ANIMATE: TargetAndTransition = { x: 0, opacity: 1 };
const DEFAULT_TRANSITION: Transition = { duration: 0.7, ease: 'easeOut' };

const DEFAULT_STAGGER = { chars: 0.05, words: 0.2, lines: 0.3 } as const;

const PIECE_STYLE: React.CSSProperties = { display: 'inline-block' };

const SplittingText: React.FC<SplittingTextProps> = (props) => (
  <ReducedMotionConfig remount>
    <SplittingTextContent {...props} />
  </ReducedMotionConfig>
);

const SplittingTextContent: React.FC<SplittingTextProps> = ({
  ref,
  text,
  type = 'chars',
  initial = DEFAULT_INITIAL,
  animate = DEFAULT_ANIMATE,
  transition: transitionProp,
  stagger,
  delay = 0,
  inView = false,
  inViewMargin = '0px',
  inViewOnce = true,
  disableAnimation = false,
  ...props
}) => {
  const { ref: localRef, isInView } = useIsInView(
    ref as React.Ref<HTMLElement>,
    {
      inView,
      inViewOnce,
      inViewMargin,
    },
  );
  const reduce = useShouldReduceMotion();
  const { tempo } = useMotionTokens();
  const defaultTransition = useTempoTransition(DEFAULT_TRANSITION);
  const transition = transitionProp ?? defaultTransition;

  const still = disableAnimation || reduce;
  const kind = Array.isArray(text) ? 'lines' : type;
  const step = stagger ?? DEFAULT_STAGGER[kind] * tempo;
  const baseDelay = delay / 1000 + (transition.delay ?? 0);

  const itemVariants: Variants = {
    hidden: still ? animate : initial,
    visible: (i: number) => ({
      ...animate,
      transition: still
        ? motionTransition.instant
        : { ...transition, delay: baseDelay + i * step },
    }),
  };

  const piece = (content: React.ReactNode, i: number, style = PIECE_STYLE) => (
    <motion.span key={i} custom={i} variants={itemVariants} style={style}>
      {content}
    </motion.span>
  );

  let visual: React.ReactNode;

  if (Array.isArray(text)) {
    visual = text.map((line, i) => (
      <React.Fragment key={`line-${i}`}>
        {piece(line, i)}
        {i < text.length - 1 ? <br /> : null}
      </React.Fragment>
    ));
  } else if (kind === 'words') {
    const tokens = text.match(/\S+\s*/g) ?? [];
    visual = tokens.map((token, i) => (
      <React.Fragment key={`word-${i}`}>
        {piece(token.trim(), i)}
        {/\s$/.test(token) ? ' ' : null}
      </React.Fragment>
    ));
  } else {
    let charIndex = 0;
    visual = text.split(/(\s+)/).map((token, wi) => {
      if (!token) return null;
      if (/^\s+$/.test(token)) return <span key={`space-${wi}`}>{token}</span>;
      return (
        <span
          key={`word-${wi}`}
          style={{ display: 'inline-block', whiteSpace: 'nowrap' }}
        >
          {splitGraphemes(token).map((char) =>
            piece(char, charIndex++, {
              ...PIECE_STYLE,
              whiteSpace: 'pre',
            }),
          )}
        </span>
      );
    });
  }

  const label = Array.isArray(text) ? text.join(' ') : text;

  return (
    <motion.span
      ref={localRef}
      data-slot="splitting-text"
      initial="hidden"
      animate={isInView || still ? 'visible' : 'hidden'}
      {...props}
    >
      <span aria-hidden="true">{visual}</span>
      <span className="sr-only" style={VISUALLY_HIDDEN}>
        {label}
      </span>
    </motion.span>
  );
};

export { SplittingText, type SplittingTextProps };

'use client';

import * as React from 'react';
import { motion, useInView, type Transition } from 'motion/react';

import {
  ReducedMotionConfig,
  motionTokens,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';
import { usePageVisible } from '../../../utils/use-page-visible';
import { VISUALLY_HIDDEN, splitGraphemes } from '../_text';

type SwappingTextDirection = 'up' | 'down';

const DEFAULT_TRANSITION: Transition = {
  duration: 0.2,
  ease: motionTokens.ease.fill,
};

const SHIFT = 0.5;
const BLUR = 'blur(2px)';

type SwappingTextProps = Omit<React.ComponentProps<'span'>, 'children'> & {
  text: string | string[];
  duration?: number;
  delay?: number;
  direction?: SwappingTextDirection;
  stagger?: number;
  transition?: Transition;
};

type Swap = {
  id: number;
  from: string[];
  to: string[];
  widths: { from: number[]; to: number[] } | null;
};

function SwappingText(props: SwappingTextProps) {
  return (
    <ReducedMotionConfig>
      <SwappingTextContent {...props} />
    </ReducedMotionConfig>
  );
}

function measure(element: HTMLElement, chars: string[]) {
  const context = document.createElement('canvas').getContext('2d');
  if (!context) return null;
  const style = getComputedStyle(element);
  context.font = style.font;
  const spacing = parseFloat(style.letterSpacing) || 0;
  return chars.map((char) => context.measureText(char).width + spacing);
}

function SwappingTextContent({
  text: textProp,
  duration = 2000,
  delay = 0,
  direction = 'up',
  stagger = 0.04,
  transition: transitionProp,
  style,
  ...props
}: SwappingTextProps) {
  const reduce = useShouldReduceMotion();
  const defaultTransition = useTempoTransition(DEFAULT_TRANSITION);
  const transition = transitionProp ?? defaultTransition;
  const ref = React.useRef<HTMLSpanElement>(null);
  const texts = Array.isArray(textProp) ? textProp : [textProp];
  const count = texts.length;
  const [index, setIndex] = React.useState(0);
  const onScreen = useInView(ref);
  const pageVisible = usePageVisible();
  const cycling = count > 1 && onScreen && pageVisible;
  const [hasCycled, setHasCycled] = React.useState(false);

  React.useEffect(() => {
    if (!cycling) return;
    const timeoutId = setTimeout(
      () => {
        setHasCycled(true);
        setIndex((current) => (current + 1) % count);
      },
      hasCycled ? duration : delay + duration,
    );
    return () => clearTimeout(timeoutId);
  }, [cycling, index, count, duration, delay, hasCycled]);

  const text = texts[index % count] ?? '';
  const chars = React.useMemo(() => splitGraphemes(text), [text]);
  const [swap, setSwap] = React.useState<Swap>(() => ({
    id: 0,
    from: chars,
    to: chars,
    widths: null,
  }));

  const doneRef = React.useRef(0);
  React.useLayoutEffect(() => {
    doneRef.current = 0;
  }, [swap.id]);

  React.useLayoutEffect(() => {
    setSwap((current) => {
      if (current.to.join('') === chars.join('')) return current;
      const element = ref.current;
      const from = measure(element!, current.to);
      const to = measure(element!, chars);
      return {
        id: current.id + 1,
        from: current.to,
        to: chars,
        widths: from && to ? { from, to } : null,
      };
    });
  }, [chars]);

  const slots = Math.max(swap.from.length, swap.to.length);
  const sign = direction === 'up' ? 1 : -1;
  const enter = `${sign * SHIFT}em`;
  const exit = `${-sign * SHIFT}em`;
  let order = 0;
  const swapping = Array.from(
    { length: slots },
    (_, i) => (swap.from[i] ?? '') !== (swap.to[i] ?? ''),
  ).filter(Boolean).length;
  const settle = () => {
    doneRef.current += 1;
    if (doneRef.current < swapping) return;
    const id = swap.id;
    setSwap((current) =>
      current.id === id
        ? { ...current, from: current.to, widths: null }
        : current,
    );
  };

  return (
    <span
      ref={ref}
